import {createSurface} from './surface.js';
const p=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step});
export const PHOTO_MOTION={glasslens:{name:'游动折射镜',cat:'摄影',icon:'◉',desc:'局部放大与柔边色散，运动随图片内容折射',params:[p('amount','折射强度',0,100,28),p('size','镜片半径 %',8,60,26),p('speed','循环圈数',0,4,1),p('x','中心 X %',0,100,62),p('y','中心 Y %',0,100,42)]},lightcurtain:{name:'窗光流帘',cat:'摄影',icon:'◫',desc:'柔和斜向光幕掠过原图，保留主体细节',params:[p('amount','光照强度',0,100,26),p('size','光幕宽度 %',5,80,32),p('speed','循环圈数',0,4,1),p('angle','倾斜角',-60,60,-18)]},highlightstreak:{name:'高光呼吸光轨',cat:'摄影',icon:'✧',desc:'从照片高光提取横向光轨，不随机撒粒子',params:[p('amount','光轨强度',0,100,32),p('threshold','高光阈值',100,250,210),p('size','拉伸距离',5,150,65),p('speed','循环圈数',0,4,1)]},filmweave:{name:'放映机微动',cat:'摄影',icon:'▣',desc:'亚像素门片抖动与细微曝光呼吸，不重绘原图',params:[p('amount','机械微动',0,100,32),p('speed','循环圈数',0,4,1),p('light','曝光呼吸',0,40,8)]}};
const fx=(type,params={})=>({type,params});
export const PHOTO_PRESETS=[{name:'玻璃漫游',en:'WANDERING GLASS',cat:'摄影',chain:[fx('glasslens'),fx('grain',{amount:6,speed:0})]},{name:'午后光帘',en:'AFTERNOON CURTAIN',cat:'摄影',chain:[fx('lightcurtain'),fx('film',{amount:20,fade:4})]},{name:'午夜镜头',en:'MIDNIGHT OPTICS',cat:'摄影',chain:[fx('highlightstreak'),fx('grain',{amount:7,speed:0})]},{name:'私人放映',en:'PRIVATE PROJECTOR',cat:'复古',chain:[fx('filmweave'),fx('film',{amount:35,fade:7}),fx('grain',{amount:12,speed:0})]}];
export function applyPhotoMotion(c,e,t=0,duration=5){const w=c.width,h=c.height,x=c.getContext('2d',{willReadFrequently:true}),p=e.params,m=p.amount/100,phase=2*Math.PI*t/duration*Math.round(p.speed);if(!m)return c;const source=createSurface(w,h);source.getContext('2d').drawImage(c,0,0);
 if(e.type==='glasslens'){const im=x.getImageData(0,0,w,h),a=im.data,raw=new Uint8ClampedArray(a),cx=(p.x/100+Math.sin(phase)*.12)*w,cy=(p.y/100+Math.cos(phase)*.07)*h,r=Math.min(w,h)*p.size/100;for(let yy=Math.max(0,Math.floor(cy-r));yy<Math.min(h,cy+r);yy++)for(let xx=Math.max(0,Math.floor(cx-r));xx<Math.min(w,cx+r);xx++){const dx=xx-cx,dy=yy-cy,d=Math.hypot(dx,dy)/r;if(d>=1)continue;const bend=(1-d*d)**2*m*.32,i=(yy*w+xx)*4;for(let k=0;k<4;k++){const factor=1-bend*(k===0?1.025:k===2?.975:1),sx=Math.max(0,Math.min(w-1,cx+dx*factor)),sy=Math.max(0,Math.min(h-1,cy+dy*factor)),ix=Math.floor(sx),iy=Math.floor(sy),fx=sx-ix,fy=sy-iy;let val=0;for(const [ox,oy,weight]of [[0,0,(1-fx)*(1-fy)],[1,0,fx*(1-fy)],[0,1,(1-fx)*fy],[1,1,fx*fy]])val+=raw[(Math.min(h-1,iy+oy)*w+Math.min(w-1,ix+ox))*4+k]*weight;a[i+k]=val;}}x.putImageData(im,0,0);}
 if(e.type==='lightcurtain'){x.save();x.globalCompositeOperation='source-atop';const center=(.5+.4*Math.sin(phase))*w,span=w*p.size/100,tilt=Math.tan(p.angle*Math.PI/180)*h,g=x.createLinearGradient(center-span,-h/2,center+span+tilt,h*1.5);g.addColorStop(0,'#fff3d500');g.addColorStop(.35,'#fff3d500');g.addColorStop(.5,'rgba(255,241,210,'+m*.45+')');g.addColorStop(.65,'#fff3d500');g.addColorStop(1,'#fff3d500');x.fillStyle=g;x.fillRect(0,0,w,h);x.restore();}
 if(e.type==='highlightstreak'){const z=createSurface(w,h),zx=z.getContext('2d');zx.drawImage(source,0,0);const im=zx.getImageData(0,0,w,h),a=im.data;for(let i=0;i<a.length;i+=4){const lum=.2126*a[i]+.7152*a[i+1]+.0722*a[i+2];a[i+3]*=Math.max(0,(lum-p.threshold)/(255-p.threshold));}zx.putImageData(im,0,0);const streak=createSurface(w,h),sx=streak.getContext('2d');sx.globalAlpha=1/24;sx.globalCompositeOperation='lighter';const dist=p.size*w/1200*(.7+.3*Math.sin(phase));for(let i=0;i<24;i++)sx.drawImage(z,(i/23-.5)*dist*2,0);sx.globalCompositeOperation='destination-in';sx.globalAlpha=1;sx.drawImage(source,0,0);x.save();x.globalAlpha=m*(.65+.35*Math.cos(phase));x.globalCompositeOperation='screen';x.drawImage(streak,0,0);x.restore();}
 if(e.type==='filmweave'){x.clearRect(0,0,w,h);x.save();x.translate(w/2+Math.sin(phase*7)*w*.0018*m,h/2+Math.cos(phase*11)*h*.0012*m);x.rotate(Math.sin(phase*3)*.0015*m);const zoom=1.012;x.scale(zoom,zoom);x.filter='brightness('+(1+Math.sin(phase*5)*p.light/100*.18)+')';x.drawImage(source,-w/2,-h/2);x.restore();}return c;}
